'use strict';
const $ = id => document.getElementById(id);
const S = {cases:[],selected:null,assets:new Map(),units:new Map(),acks:new Set(),map:null,mode:'dispatch',busy:false,errors:[],catalogue:null,runVersions:new Map(),tab:'Resumo',opened:false,tick:Date.now(),optional:new Map(),pinned:false};
const groups=['Aprovar meio','Resolver conflito','Ligar de volta','Confirmar resgate'];
const labels={people:'Pessoas',children:'Crianças',elderly:'Idosos',disabled:'Pessoas com deficiência / acamadas',pets:'Animais',street:'Rua',municipality:'Município',number:'Número',landmark:'Referência',risk_words:'Risco relatado',already_rescued:'Resgate relatado',conflicting_counts:'Contagens conflitantes'};
