const PRECISION={EXACT:'Exato',STREET:'Rua',LANDMARK:'Ponto de referência',AREA:'Área',AMBIGUOUS:'Ambíguo'},VERTICAL={ground:'Térreo',first_floor:'1º andar',upper_floor:'Andar superior',attic_forro:'Forro / sótão',roof:'Telhado / laje',unknown:'Nível não informado'},SENDER={on_site:'No local',third_party_elsewhere:'Terceiro, fora do local',volunteer_repost:'Mensagem repassada',crew:'Equipe',unknown:'Remetente não identificado'};
