async function refresh(){const response=await api(`/api/cases?replay_time=${encodeURIComponent((window.DeskReplay?window.DeskReplay.iso():$('date').value+'T23:59:59-03:00'))}`);S.cases=response.cases||[];hydrate();loadMode();window.DeskCoverage?.refresh();S.errors=[];totals();drawQueue();if(!selected())S.selected=sorted()[0]?.case_id||null;drawQueue();drawCase();if(S.mode==='agents')drawAgents();if(S.mode==='situation')drawSituation();}
async function mapRefresh(){try{S.map=await api(`/api/map?date=${$('date').value}`);await window.DeskMap.update(S.map,selected(),$('date').value);drawQueue();totals();}catch(e){S.map=null;S.errors.push(e.message);window.DeskMap.unavailable(e.message);notice(`Mapa: ${e.message}`,true);totals();}}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>mode(b.dataset.mode));$('search').oninput=drawQueue;$('date').onchange=async()=>{window.DeskMissions.clear();window.DeskRouteView?.hide();await refresh();await mapRefresh();drawCase();if(S.mode==='situation')drawSituation();if(S.mode==='data')drawData();};
$('system-light').onclick=()=>window.DeskFeedback.errors(S,{el,button,select,mode});
window.DeskSupervisor&&window.DeskSupervisor.init({api,el,button,notice,day:()=>$('date').value,refresh});
window.DeskTimeline&&window.DeskTimeline.init({api,el,button,notice,refresh,select:id=>{mode('dispatch');select(id);},setDay:async d=>{if($('date').value!==d){$('date').value=d;await $('date').onchange();}}});
window.DeskRedTeam&&window.DeskRedTeam.init({api,el,button,notice});
window.DeskFlow&&window.DeskFlow.init({api,el,button,evidence,openCase:id=>{mode('dispatch');select(id);setTab('Registro');}});
$('resources').onclick=()=>(window.DeskFleet||window.DeskFeedback).resources({api,el,button,notice,day:$('date').value});
$('new-request').onclick=()=>{$('received').value=`${$('date').value}T12:00`;$('new-dialog').showModal();};$('close-dialog').onclick=()=>$('new-dialog').close();
function stages(){const ol=$('run-stages');ol.replaceChildren(el('li','Pedido enviado · aguardando etapas registradas'));for(const c of S.cases){if(!(c.calls||[]).length||S.runVersions.get(c.case_id)===c.version)continue;const li=el('li',place(c));li.append(el('small',' · '+(c.calls||[]).map(x=>`${roles[x.role]||x.role} (${fmt(x.seconds)} s)`).join(' → ')));ol.append(li);}ol.append(el('li','Aguardando etapas registradas; consulta a cada 1,5 s.'));}
function liveStep(event,rows,offline=false){const role=event.role||event.stage,key=`${event.case_id||'run'}:${role}`;let item=rows.get(key);if(!item){item={node:el('li'),open:0,events:[]};rows.set(key,item);$('run-stages').append(item.node);}item.events.push(event);if(event.stage?.endsWith('_started'))item.open++;if(event.stage?.endsWith('_done')||event.stage?.endsWith('_error'))item.open=Math.max(0,item.open-1);if(event.stage==='done'||event.stage==='error'){for(const row of rows.values()){row.open=0;row.callOpen=false;row.node.classList.remove('call-open');}}
 // Location has an outer deterministic stage and an optional nested model call.
 const callOpen=!offline&&item.open>(role==='location'?1:0)&&['intake','critic','revision','location','hazard_critic','duplicate_reviewer'].includes(role);item.callOpen=callOpen;item.node.classList.toggle('call-open',callOpen);const state=event.stage?.endsWith('_error')||event.stage==='error'?'falhou':item.open?'em andamento':'registrado';item.node.classList.toggle('failed',state==='falhou');item.node.replaceChildren(el('strong',`${event.case_id||'Execução'} · ${roles[role]||role} · ${state}`),el('p',`${event.model||'Modelo não informado'} · ${num(event.seconds)?fmt(event.seconds)+' s':'duração não informada'}`),evidence('Eventos / comprovante',item.events));return item;}
async function awaitRun(start){if(!start.run_id)return start;let stream=null;const rows=new Map();S.liveRows=rows;$('run-stages').replaceChildren();let offline=false;try{offline=(await api('/api/health')).SAMPLE_MODE===true;}catch{}
 function show(event){liveStep(event,rows,offline);if(event.case_id===S.selected&&(S.tab==='Registro'||S.pinned))drawCase();window.DeskLive?.runEvent(event);}
 if(window.EventSource){stream=new EventSource(`/api/runs/${encodeURIComponent(start.run_id)}/events`);for(const name of ['intake','critic','revision','location','hazard_critic','duplicate_reviewer'])for(const suffix of ['started','done','error'])stream.addEventListener(name+'_'+suffix,e=>{try{show(JSON.parse(e.data));}catch{}});for(const name of ['received','checks_done','decision','done','error'])stream.addEventListener(name,e=>{if(e.data)try{show(JSON.parse(e.data));}catch{}});stream.onerror=()=>{stream.close();for(const row of rows.values()){row.callOpen=false;row.node.classList.remove('call-open');row.node.append(el('small','Stream interrompido · estado da chamada desconhecido'));}stream=null;};}
 try{for(let i=0;i<330;i++){const state=await api(`/api/runs/${encodeURIComponent(start.run_id)}`);if(!stream)for(const e of state.events||[])show(e);if(state.status==='failed')throw new Error(state.result?.error||'Falha na análise.');if(state.status==='complete')return state.result;await new Promise(resolve=>setTimeout(resolve,1500));}throw new Error('Tempo de acompanhamento esgotado. Consulte a fila antes de repetir o pedido.');}finally{stream?.close();for(const row of rows.values()){row.callOpen=false;row.node.classList.remove('call-open');}S.liveRows=null;if(S.tab==='Registro'||S.pinned)drawCase();}}
$('request-form').onsubmit=async e=>{e.preventDefault();$('submit-request').disabled=true;const started=performance.now();S.runVersions=new Map(S.cases.map(c=>[c.case_id,c.version]));stages();try{const replay=(window.DeskReplay?window.DeskReplay.iso():$('date').value+'T23:59:59-03:00');const start=await api('/run',{async:true,replay_time:replay,messages:[{text:$('request-text').value,received_at:`${$('received').value}:00-03:00`}]});const r=await awaitRun(start);await refresh();await mapRefresh();if(r.cases?.length)select(r.cases[0].case_id);$('run-stages').append(el('li',`${r.partial?'Análise parcial':'Análise concluída'} · ${fmt(r.seconds??(performance.now()-started)/1000)} s`));notice('Análise recebida. Revise o pedido antes de aprovar um meio.');}catch(err){notice(err.message,true);$('run-stages').append(el('li',err.message,'danger'));}finally{$('submit-request').disabled=false;}};
$('toggle-queue').onclick=()=>{const closed=$('dispatch').classList.toggle('queue-closed');$('toggle-queue').textContent=closed?'›':'‹';$('toggle-queue').setAttribute('aria-expanded',String(!closed));$('toggle-queue').setAttribute('aria-label',closed?'Expandir fila':'Recolher fila');window.DeskMap.resize();};
$('back-dispatch').onclick=()=>mode('dispatch');$('open-case').onclick=()=>openPanel(true);
document.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(key==='escape'){if(document.querySelector('dialog[open]'))return;openPanel(false);$('layers-menu').open=false;mode('dispatch');return;}if(e.ctrlKey||e.metaKey||e.altKey||document.querySelector('dialog[open]')||(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||key==='enter'&&['BUTTON','SUMMARY'].includes(e.target.tagName))||e.target.isContentEditable)return;if(key==='/'){e.preventDefault();mode('dispatch');$('search').focus();}if(key==='j'||key==='k'){e.preventDefault();const q=sorted().filter(c=>(place(c)+' '+(c.text||'')).toLocaleLowerCase().includes($('search').value.toLocaleLowerCase())),index=q.findIndex(c=>c.case_id===S.selected),c=q[Math.max(0,Math.min(q.length-1,index+(key==='j'?1:-1)))];if(c){select(c.case_id,false);$('queue').querySelector('.selected')?.scrollIntoView({block:'nearest'});}}if(key==='enter'&&selected()){e.preventDefault();openPanel(true);}if(key==='a'&&selected()){e.preventDefault();openPanel(true);setTab('Meios');$('case').querySelector('input[name=asset]:not(:disabled)')?.focus();}if(key==='r'&&selected()){e.preventDefault();openPanel(true);setTab('Retorno');$('contact-reply')?.focus();}if(key==='c'&&selected()){e.preventDefault();dispatchCard(selected());}});
setInterval(()=>{if(!S.busy&&!document.querySelector('dialog[open]')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))refresh().catch(()=>{});},60000);
setInterval(()=>{for(const n of document.querySelectorAll('[data-timer]')){const c=S.cases.find(c=>c.case_id===n.dataset.timer);if(c){n.textContent=elapsed(c);n.className='elapsed'+(age(c)>24?' red':age(c)>6?' amber':'');}}totals();},1000);
(async()=>{await window.DeskMap.init(id=>{mode('dispatch');select(id);});try{await refresh();await mapRefresh();}catch(e){S.errors.push(e.message);notice(e.message,true);totals();}})();
// ---- UXA: dock "Agentes ao vivo", menu "Mais" e agrupamento das ferramentas secundárias da barra superior
(()=>{
 const live=window.DeskLive;if(live){const dock=document.createElement('section');dock.id='live-dock';document.body.append(dock);
  live.init({api,el,button,evidence,selected:()=>S.selected,selectedCase:()=>selected(),agentLine,openCase:id=>{mode('dispatch');select(id);setTab('Registro');},openFull:()=>mode('flow')});live.mountDock(dock);}
 const bar=document.querySelector('.status-bar'),list=document.querySelector('#more-menu .more-list'),keep=new Set(['new-request','system-light','supervisor-toggle','timeline-toggle','live-open','more-btn']);
 const sweep=()=>{for(const b of bar.querySelectorAll(':scope > button')){if(!keep.has(b.id)){b.classList.add('more-item');list.append(b);}}};
 if(bar&&list){sweep();new MutationObserver(sweep).observe(bar,{childList:true});document.addEventListener('click',e=>{const m=$('more-menu');if(m.open&&!m.contains(e.target))m.open=false;});
  list.addEventListener('click',()=>{$('more-menu').open=false;});}
 $('live-open').onclick=()=>S.mode==='flow'?mode('dispatch'):mode('flow');
})();
// ---- UX2: small public surface for the Meios / route view / replay / intake modules
window.DeskApp={S,redraw:()=>drawCase(),setTab,select:id=>{mode('dispatch');select(id);},place,
  pos:c=>{const p=S.map?.cases?.find(x=>x.case_id===c.case_id);return p&&Number.isFinite(p.lon)&&Number.isFinite(p.lat)?[p.lon,p.lat]:null;},
  refresh:()=>refresh(),mapRefresh:()=>mapRefresh(),drawQueue:()=>drawQueue()};
